<!--vbase-->
<template>
  <span class="footer-link inline-flex items-center gap-2" @click="navigateToFormBuilder">
    <q-spinner-ios v-if="loading_templates" color="primary" size="1em" />
    {{ $t('edit_layout') }}
  </span>
</template>

<script lang="ts">
import { storeToRefs } from 'pinia';
// import { LocalStorage } from 'quasar';
import { defineComponent, ref } from 'vue';
import { useFormBuilderStore } from 'src/store/main';
import { formBuilderRouter } from 'src/formBuilder/utils/formBuilderRouter';

export default defineComponent({
  el: '#app',
  mixins: [],
  components: {},
  props: {
    doc_type_key: {
      type: String,
      default: '',
    },
    sub_doc_type_key: {
      type: String,
      default: '',
    },
    extraction_type: {
      type: String,
      default: '',
    },
  },
  watch: {
    loading_templates: {
      handler: function (newVal, oldVal) {
        this.setTemplateId();
      },
    },
  },
  data() {
    return {
      layout_template_id: ref(''),
    };
  },
  mounted: function () {
    this.setTemplateId();
  },
  methods: {
    setTemplateId() {
      try {
        if (typeof this.document_type_templates.filter !== 'function') {
          return;
        }
        let filterRecord = this.document_type_templates.filter((v: any) => {
          const isDocTypeMatch = v.doc_type_key == this.doc_type_key;

          if (this.sub_doc_type_key) {
            return (
              isDocTypeMatch && v.sub_doc_type_key == this.sub_doc_type_key
            );
          }

          return isDocTypeMatch && !v.sub_doc_type_key;
        });
        filterRecord = filterRecord[0] || null;
        this.layout_template_id = !filterRecord ? '' : filterRecord.id;
      } catch (err) {
        logError(err);
      }
    },
    navigateToFormBuilder() {
      if (this.loading_templates) {
        return;
      }
      const url = formBuilderRouter.getDetailViewRoute({
        doc_type_key: this.doc_type_key || '',
        layout_template_id: this.layout_template_id || '',
        sub_doc_type_key: this.sub_doc_type_key || '',
      });

      if (!url) {
        logInfo('missing params for url');
      }

      // let allow_selection = (this.extraction_type && this.extraction_type === 'FLEX_COORDINATES') ? true : false;
      // LocalStorage.set('allow_selection', allow_selection);

      this.$router.push(url);
    },
  },
  setup() {
    const form_builder_store = useFormBuilderStore();
    const { loading_templates, document_type_templates } =
      storeToRefs(form_builder_store);

    return {
      loading_templates,
      document_type_templates,
    };
  },
});
</script>

